(function(root){'use strict';const C=root.DemoConfig||(typeof require==='function'?require('./config.js'):null);
function execute(i){if(i.business!=='gilligan')return {status:'blocked',code:'UNSUPPORTED_BUSINESS',reason:'本地样板仅实现吉利根流程，Robert现有功能未修改。'};if(!i.material?.trim())return {status:'blocked',code:'MISSING_INPUT',reason:'请填写原稿或选题方向。'};if(!['generate','evaluate','search','revise'].includes(i.operation))return {status:'blocked',code:'UNKNOWN_OPERATION',reason:'处理方式不可用，请返回新建内容。'};if(i.scenario==='missing')return {status:'blocked',code:'INSUFFICIENT_EVIDENCE',reason:'没有可用演示依据，未生成或补造学问。请补充授权材料，或切换有依据场景。'};if(i.scenario==='offline')return {status:'error',code:'BRIDGE_OFFLINE',reason:'模拟执行服务离线。原输入保留，请稍后重试。'};if(i.scenario==='quota')return {status:'error',code:'QUOTA_EXCEEDED',reason:'模拟额度不足。请联系管理员检查预算，不自动切换模型。'};let content=i.material.trim();if(i.operation==='generate')content='【合成流程演示 · 非真实AI生成】\n\n'+content+'\n\n也许，我们可以从一个小小的选择开始。此刻，你愿意先尝试哪一步？';if(i.operation==='revise'){if(!i.revision?.trim())return {status:'blocked',code:'MISSING_REVISION',reason:'请填写本轮修改要求。'};content=i.material+'\n\n【本轮修改演示】\n已记录要求：'+i.revision+'\n仅演示版本继承，不执行真实语义改写。';}if(i.retain?.trim()&&!content.includes(i.retain.trim()))content+='\n\n必须保留：'+i.retain.trim();return {status:'completed',content,sources:C.sources.map(x=>({...x})),assessment:i.operation==='evaluate'?{fidelity:{level:'示例：需核对',reason:'仅演示来源与判断分开呈现，未执行真实学问评价。'},expression:{level:'示例：基本贴近',reason:'只展示温和坚定、口语化和开放式提问的评价结构，不是本人认定概率。'},issues:[{fragment:i.material.slice(0,45),suggestion:'核对原始课程或著作；转述不能当原话。',source:'DEMO-SOURCE-01'}]}:null,model_called:false,token_usage:null,cost:null};}
function visibleHistory(rs,b,u,a){return rs.filter(x=>x.business===b&&(a||x.owner===u));}
function snapshot(r,actor,direct){return {id:'review-'+Date.now()+'-'+Math.random().toString(16).slice(2),recordId:r.id,business:r.business,owner:r.owner,submitter:actor,title:r.title,content:r.content,sourceVersion:r.version,sources:r.sources,status:direct?'approved':'pending',submittedAt:new Date().toISOString(),reviewer:direct?actor:null};}
root.DemoAdapter={execute,visibleHistory,snapshot};if(typeof module!=='undefined')module.exports=root.DemoAdapter;})(globalThis);
